import type {IncomingMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limitError = validateMessageLimit(message);
  if (limitError) return limitError;

  const beforeError = validateMessageBefore(message);
  if (beforeError) return beforeError;

  const result: {type: 'list_sessions'; limit?: number; before?: {sessionId: string; updatedAt: string}} = {
    type: 'list_sessions',
  };

  if (message.limit !== undefined) {
    result.limit = message.limit as number;
  }

  if (message.before !== undefined && message.before !== null) {
    const before = message.before as Record<string, unknown>;
    result.before = {
      sessionId: before.sessionId as string,
      updatedAt:
        typeof before.updatedAt === 'string'
          ? (before.updatedAt as string)
          : new Date(before.updatedAt as number).toISOString(),
    };
  }

  return {
    valid: true,
    data: result,
  };
}

function validateMessageLimit(message: Record<string, unknown>): ValidationResult | null {
  if (message.limit !== undefined && !isValidLimit(message.limit)) {
    return {valid: false, error: 'limit must be an integer between 1 and 200'};
  }
  return null;
}

function validateMessageBefore(message: Record<string, unknown>): ValidationResult | null {
  if (message.before === undefined) {
    return null;
  }

  if (typeof message.before !== 'object' || message.before === null) {
    return {valid: false, error: 'before must be an object with sessionId and updatedAt'};
  }

  const before = message.before as Record<string, unknown>;

  if (!isValidSessionId(before.sessionId)) {
    return {valid: false, error: 'before.sessionId must be a string between 1 and 128 characters'};
  }

  if (!isValidUpdatedAt(before.updatedAt)) {
    return {valid: false, error: 'before.updatedAt must be a date string or number'};
  }

  const parsedDate =
    typeof before.updatedAt === 'string' ? Date.parse(before.updatedAt as string) : (before.updatedAt as number);
  if (isNaN(parsedDate) || !isFinite(parsedDate)) {
    return {valid: false, error: 'before.updatedAt must be a valid date'};
  }

  return null;
}

function isValidLimit(limit: unknown): boolean {
  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 1 && limit <= 200;
}

function isValidSessionId(sessionId: unknown): boolean {
  return typeof sessionId === 'string' && sessionId.length >= 1 && sessionId.length <= 128;
}

function isValidUpdatedAt(updatedAt: unknown): boolean {
  return typeof updatedAt === 'string' || typeof updatedAt === 'number';
}

